/**
 * @brief 对跨板级联转发帧执行 hop_limit 递减、置位路由标志并重算 CRC16
 * @param frame   输入原始协议帧指针
 * @param len     协议帧总字节数
 * @param out_buf 输出重打包后的协议帧缓冲区
 */
static void relay_frame(const uint8_t *frame, uint16_t len, uint8_t *out_buf)
{
    if ((frame == NULL) || (out_buf == NULL) || (len < 14U))
    {
        return;
    }
    for (uint16_t i = 0U; i < len; ++i)
    {
        out_buf[i] = frame[i];
    }
    out_buf[6] = (uint8_t)(frame[6] - 1U);
    out_buf[7] = (uint8_t)(frame[7] | MINIMC_ROUTE_IS_ROUTED);
    const uint16_t new_crc = minimc_crc16(out_buf, (uint16_t)(len - 2U));
    out_buf[len - 2U] = (uint8_t)(new_crc & 0xFFU);
    out_buf[len - 1U] = (uint8_t)((new_crc >> 8U) & 0xFFU);
}

