/**
 * @brief 校验平面 A (AP→TH) L3 帧头控制位、水平分割、静态路由与跳数（严禁读取或判断 cmd_id/payload）
 * @param frame 完整物理帧指针
 * @return true 允许执行 L3 转发，false 触发规范丢弃并累计统计
 */
static bool check_ap_to_th_l3_route(const uint8_t *frame)
{
    const uint8_t src_id = frame[2];
    const uint8_t dst_id = frame[3];
    const uint8_t hop_limit = frame[6];
    const uint8_t route_ctrl = frame[7];
    if ((route_ctrl & 0x03U) == 0x03U)
    {
        s_l3_err_invalid_ctrl++;
        return false;
    }
    if ((src_id == MINIMC_NODE_MC) || (dst_id == MINIMC_NODE_AP))
    {
        s_l3_err_bad_route++;
        return false;
    }
    if (dst_id != MINIMC_NODE_TH)
    {
        s_l3_err_no_route++;
        return false;
    }
    if (hop_limit <= 1U)
    {
        s_l3_err_hop_exhausted++;
        return false;
    }
    return true;
}

/**
 * @brief 平面 A (AP→TH) L3 无状态透明存储转发：零业务解析与零伪造 NACK，成功后刷新 5000ms 租约
 * @param frame 完整请求帧指针
 * @param len 帧总长度
 */
static void forward_ap_to_th_l3(const uint8_t *frame, uint16_t len)
{
    if ((frame == NULL) || (len < 14U))
    {
        return;
    }
    if (!check_ap_to_th_l3_route(frame))
    {
        return;
    }
    const forward_uart_mode_t uart_mode = forward_uart_mode_get();
    const uint16_t seq = (uint16_t)frame[8] | (uint16_t)((uint16_t)frame[9] << 8U);
    if ((uart_mode == FORWARD_UART_MODE_UPGRADE) || (uart_mode == FORWARD_UART_MODE_PERF_TEST))
    {
        s_l3_err_tx_drop++;
        /* 仅在 TX_ERR 诊断日志中被动记录序号与命令字节，L3 转发路径严禁依 cmd_id 裁决 */
        mc_dbg_log_tx_err("TH", seq, frame[5]);
        return;
    }
    relay_frame(frame, len, s_ap_to_th_relay_buf);
    if (!forward_uart_send_raw(s_ap_to_th_relay_buf, len))
    {
        s_l3_err_tx_drop++;
        mc_dbg_log_tx_err("TH", seq, frame[5]);
        return;
    }
    s_th_l3_lease_active = true;
    s_th_l3_lease_last_ms = wk_timebase_get();
    forward_uart_mode_set(FORWARD_UART_MODE_OTA_ROUTE);
}

