/**
 * @brief 验证平面 A L3 租约期内 AP→TH (DST=0x03) 零拦截透传与 TH→AP (DST=0x01) 零审查回传
 */
static void test_l3_transparent_forward_bidirectional(void)
{
    minimc_proto_init();
    uint8_t ota_pay[520];
    for (uint16_t i = 0U; i < sizeof(ota_pay); ++i) { ota_pay[i] = (uint8_t)(i & 0xFFU); }

    /* 1. AP->TH 534B 0x21 触发 L3 租约与 OTA_ROUTE，且不置位 s_mc_local_relay_pending */
    send_ap_frame(MINIMC_NODE_TH, 0x05U, MINIMC_CMD_OTA_DATA, ota_pay);
    require_true(minimc_proto_is_th_proxy_active() && forward_uart_mode_get() == FORWARD_UART_MODE_OTA_ROUTE, "L3 lease enabled");
    require_true(!minimc_proto_is_th_relay_pending() && s_last_th_tx_len == 534U && s_last_ap_tx_len == 0U, "534B L3 forwarded");
    require_true(s_last_th_tx[5] == MINIMC_CMD_OTA_DATA && s_last_th_tx[6] == 3U && s_last_th_tx[7] == MINIMC_ROUTE_IS_ROUTED, "L3 hop/routed updated");

    /* 2. L3 租约期内向 DST=0x03 下发 0x24/0x14/0x01/0xFE 零拦截无篡改透传 */
    const uint8_t cmds[4] = { MINIMC_CMD_OTA_ABORT, MINIMC_CMD_GET_TEMP, MINIMC_CMD_GET_VERSION, 0xFEU };
    const uint8_t probe_pay[4] = { 0x12U, 0x34U, 0x56U, 0x78U };
    for (uint8_t idx = 0U; idx < 4U; ++idx)
    {
        const test_frame_spec_t req = { MINIMC_NODE_AP, MINIMC_NODE_TH, 0x05U, cmds[idx], 4U, 0U, (uint16_t)(10U + idx), probe_pay, 4U };
        send_ap_spec_frame(&req);
        require_true(s_last_ap_tx_len == 0U && s_last_th_tx_len == 18U && s_last_th_tx[5] == cmds[idx], "L3 AP->TH zero cmd_id interception");
        require_true(memcmp(&s_last_th_tx[12], probe_pay, 4U) == 0 && !minimc_proto_is_th_relay_pending(), "L3 payload intact");
    }

    /* 3. SRC=0x03->DST=0x01 任意响应(含 NACK 0x04 / 未登记 0xFE / 主动上报 0x40)零 pending 检查直转 AP，且 0x22 ACK 不清租约 */
    const uint8_t nack_pay[3] = { 0x04U, 0x34U, 0x12U };
    const test_frame_spec_t th_nack = { MINIMC_NODE_TH, MINIMC_NODE_AP, 0x06U, MINIMC_CMD_NACK, 4U, 0U, 0x1234U, nack_pay, 3U };
    inject_th_spec_frame(&th_nack, true);
    require_true(s_last_ap_tx_len == 17U && s_last_ap_tx[2] == MINIMC_NODE_TH && s_last_ap_tx[5] == MINIMC_CMD_NACK && s_last_ap_tx[12] == 0x04U, "TH NACK 0x04 relayed");
    const test_frame_spec_t th_unreg = { MINIMC_NODE_TH, MINIMC_NODE_AP, 0x06U, 0xFEU, 4U, 0U, 0x2345U, probe_pay, 4U };
    inject_th_spec_frame(&th_unreg, true);
    require_true(s_last_ap_tx_len == 18U && s_last_ap_tx[5] == 0xFEU && s_last_ap_tx[8] == 0x45U, "unregistered TH->AP relayed");
    const test_frame_spec_t th_unsol = { MINIMC_NODE_TH, MINIMC_NODE_AP, 0x04U, 0x40U, 4U, 0U, 0x5678U, probe_pay, 4U };
    inject_th_spec_frame(&th_unsol, true);
    require_true(s_last_ap_tx_len == 18U && s_last_ap_tx[5] == 0x40U && memcmp(&s_last_ap_tx[12], probe_pay, 4U) == 0, "unsolicited TH->AP relayed");
    const uint8_t ack_pay[4] = { 16U, 8U, 0U, 0U };
    const test_frame_spec_t th_fin_ack = { MINIMC_NODE_TH, MINIMC_NODE_AP, 0x06U, MINIMC_CMD_ACK, 4U, 0U, 0x0022U, ack_pay, 4U };
    inject_th_spec_frame(&th_fin_ack, true);
    require_true(s_last_ap_tx_len == 18U && minimc_proto_is_th_proxy_active(), "L3 lease NOT peek-cleared on 0x22/0x00");
}

