    clear_usart1_capture();
    /* 无任何本地级联在途时，DST=0x01 的 NACK 0x04 / 未登记 0xFE / 主动上报 0x40 无条件透传回 AP */
    inject_th_custom_frame(MINIMC_CMD_NACK, 0x0099U, nack_pay, 3U);
    assert(s_ap_tx_count == tx_base + 1U && s_last_ap_tx_frame[5] == MINIMC_CMD_NACK && s_last_ap_tx_frame[12] == 0x04U);
    inject_th_custom_frame(0xFEU, 0x0123U, unsol_pay, 4U);
    assert(s_ap_tx_count == tx_base + 2U && s_last_ap_tx_frame[5] == 0xFEU && memcmp(&s_last_ap_tx_frame[12], unsol_pay, 4U) == 0);
    inject_th_frame_hdr(MINIMC_NODE_AP, MINIMC_FLAG_PROTO_V2, 0x40U, 0x0456U);
    assert(s_ap_tx_count == tx_base + 3U && s_last_ap_tx_frame[5] == 0x40U && s_last_ap_tx_frame[8] == 0x56U);
    assert(strstr(s_usart1_tx_capture, "BAD_FRAME") == NULL);

    /* 在 L3 租约期内向 DST=0x03 下发 0x24/0x14/0x01/0xFE 全部零拦截透传，且不触发本地 pending */
    const uint8_t cmds[4] = { MINIMC_CMD_OTA_ABORT, MINIMC_CMD_GET_TEMP, MINIMC_CMD_GET_VERSION, 0xFEU };
