/**
 * @brief 由 MC 向 TH 发起平面 B 本地级联控制帧 (SRC=0x02, 0x10/0x19/0x1C) 并登记 200ms 超时跟踪
 * @param cmd_id 级联控制命令码
 * @param seq 16位序列号
 * @param payload 载荷数据指针
 * @param plen 载荷长度
 */
static void trigger_mc_to_th_cascade(uint8_t cmd_id, uint16_t seq, const void *payload, uint16_t plen)
{
    const bool link_busy = s_mc_local_relay_pending || mc_is_th_cascade_yielded();
    const bool bad_plen = (plen > MINIMC_MAX_PAYLOAD_SIZE);
    if (link_busy || bad_plen)
    {
        mc_dbg_log_tx_err("TH", seq, cmd_id);
        return;
    }
    static uint8_t frame[MINIMC_MAX_FRAME_SIZE];
    frame[0] = MINIMC_SOF_1;
    frame[1] = MINIMC_SOF_2;
    frame[2] = MINIMC_NODE_MC;
    frame[3] = MINIMC_NODE_TH;
    frame[4] = (uint8_t)(MINIMC_FLAG_WANTS_ACK | MINIMC_FLAG_PROTO_V2);
    frame[5] = cmd_id;
    frame[6] = MINIMC_DEFAULT_HOP_LIMIT;
    frame[7] = MINIMC_DEFAULT_ROUTE;
    frame[8] = (uint8_t)(seq & 0xFFU);
    frame[9] = (uint8_t)((seq >> 8U) & 0xFFU);
    frame[10] = (uint8_t)(plen & 0xFFU);
    frame[11] = (uint8_t)((plen >> 8U) & 0xFFU);
    if ((plen > 0U) && (payload != NULL))
    {
        (void)memcpy(frame + MINIMC_HEADER_SIZE, payload, plen);
    }
    const uint16_t body_len = (uint16_t)(MINIMC_HEADER_SIZE + plen);
    const uint16_t crc = minimc_crc16(frame, body_len);
    frame[body_len] = (uint8_t)(crc & 0xFFU);
    frame[body_len + 1U] = (uint8_t)((crc >> 8U) & 0xFFU);
    if (!forward_uart_send_raw(frame, (uint16_t)(body_len + MINIMC_CRC_SIZE)))
    {
        mc_dbg_log_tx_err("TH", seq, cmd_id);
        return;
    }
    s_mc_local_relay_pending = true;
    s_mc_local_relay_seq = seq;
    s_mc_local_relay_cmd = cmd_id;
    s_mc_local_relay_start_ms = wk_timebase_get();
    const mc_dbg_meta_t rtx_meta = { "RELAY_TX", "TH", seq, cmd_id, "EXEC" };
    mc_dbg_emit(&rtx_meta, "timeout_ms=200");
}

/**
 * @brief 处理 0x10 (SET_TEMP) 设定温度控制命令并级联同步至 TH（L3 租约期主动让路）
 * @param seq 16位序列号
 * @param frame 完整请求帧指针
 * @param plen 载荷长度
 */
static void handle_mc_set_temp(uint16_t seq, const uint8_t *frame, uint16_t plen)
{
    if ((frame == NULL) || (plen < sizeof(minimc_set_temp_req_t)))
    {
        send_mc_nack(frame, seq, 0x02U);
        return;
    }
    if (mc_is_th_cascade_yielded())
    {
        /* 平面 A L3 租约或串口独占模式激活时让路返回 0x05，不触碰 USART6 亦不覆写本地温度目标 */
        send_mc_nack(frame, seq, MINIMC_ERR_DEVICE_BUSY);
        return;
    }
    minimc_set_temp_req_t req;
    (void)memcpy(&req, frame + MINIMC_HEADER_SIZE, sizeof(req));
    int16_t nozzle_ddC = s_dbg_state.nozzle_set_ddC;
    int16_t bed_ddC = s_dbg_state.bed_set_ddC;
    if (req.nozzle_target_deci_c >= 0)
    {
        nozzle_ddC = req.nozzle_target_deci_c;
    }
    if (req.bed_target_deci_c >= 0)
    {
        bed_ddC = req.bed_target_deci_c;
        Heater_set_target_temperature(&Platform, (int16_t)(bed_ddC / 10));
    }
    s_dbg_state.ack_seq = seq;
    mc_debug_notify_temp_target(nozzle_ddC, bed_ddC);
        send_mc_nack(frame, seq, MINIMC_ERR_COMMAND_REJECTED);
        return;
    }
    minimc_ack_payload_t ack_pay;
    build_mc_ack_payload(&ack_pay);
    if (req.action == 0U)
    {
        (void)send_mc_ack_frame(MINIMC_CMD_ACK, seq, &ack_pay, sizeof(ack_pay));
        return;
    }
    const bool job_busy = (s_dbg_state.job_state_id != 0U) &&
                          (s_dbg_state.job_state_id != 4U) &&
                          (s_dbg_state.job_state_id != 5U);
    const bool motion_or_job_busy = (movesplanned() > 0U) || job_busy;
    const bool heater_busy = (s_dbg_state.nozzle_set_ddC > 0) || (s_dbg_state.bed_set_ddC > 0);
    /* 平面 B 0x1D 仅核对本机运动/作业/加热与 App 忙钩子，不再被平面 A 5000ms L3 租约误拦 */
    const bool app_busy = mc_app_is_busy_hook();
    if (motion_or_job_busy || heater_busy || app_busy)
    {
        send_mc_nack(frame, seq, MINIMC_ERR_DEVICE_BUSY);
        return;
    }
    Heater_set_target_temperature(&Extruder_One, 0);
    Heater_set_target_temperature(&Platform, 0);
    s_dbg_state.nozzle_set_ddC = 0;
    s_dbg_state.bed_set_ddC = 0;
    quickStop();
    mc_disable_all_steppers_hook();
    (void)send_mc_ack_frame(MINIMC_CMD_ACK, seq, &ack_pay, sizeof(ack_pay));
    mc_exec_controlled_reset(req.action, req.delay_ms);
}

