    }
    char gcode[61];
    (void)memcpy(gcode, frame + MINIMC_HEADER_SIZE + 2U, line_len);
    gcode[line_len] = '\0';
    if (!mc_proto_enqueue_gcode(gcode))
    {
        send_mc_nack(frame, seq, MINIMC_ERR_DEVICE_BUSY);
        return;
    }
    mc_apply_gcode_side_effects(gcode, seq);
    minimc_gcode_resp_t resp_pay = { 0U, 4U, seq };
    const bool tx_ok = send_mc_ack_frame(MINIMC_CMD_GCODE_EXEC, seq, &resp_pay, sizeof(resp_pay));
    char kv[96];
    (void)snprintf(kv, sizeof(kv), "gcode_len=%u status=OK", (unsigned int)line_len);
    return true;
}

/**
 * @brief 检查平面 A L3 活跃租约 5000ms 静默超时并自动恢复 USART6 常规模式（含 32 位半空间回绕保护）
 * @param now_ms 当前系统毫秒计数
 */
static void check_th_l3_lease_timeout(uint32_t now_ms)
{
    if (!s_th_l3_lease_active)
    {
        return;
    }
    /* 采用 < 0x80000000UL 半空间差值过滤同轮跨毫秒下溢并兼容 32 位 SysTick 回绕 */
    const uint32_t lease_elapsed = (uint32_t)(now_ms - s_th_l3_lease_last_ms);
    if ((lease_elapsed < 0x80000000UL) && (lease_elapsed >= MC_TH_PROXY_TIMEOUT_MS))
    {
        s_th_l3_lease_active = false;
        if (forward_uart_mode_get() == FORWARD_UART_MODE_OTA_ROUTE)
        {
            forward_uart_mode_set(FORWARD_UART_MODE_NORMAL);
        }
    }
}

